529	fn run_blocked<B: Bench>(
530	    bench: &mut B,
531	    pipeline: &mut BatchPipeline,
532	    blocks: u64,
533	    outer_override: Option<u64>,
534	    target_seconds: f64,
535	    inner: u64,
536	) -> (f64, BlockStats) {
537	    let mut dither = Dither::new();
538	    let mut means: Vec<f64> = Vec::with_capacity(blocks as usize);
539	    let run_start = std::time::Instant::now();
540	    for b in 0..blocks {
541	        let ms =
542	            BLOCK_SLEEP_MS_MIN + dither.rand_u64() % (BLOCK_SLEEP_MS_MAX - BLOCK_SLEEP_MS_MIN + 1);
543	        std::thread::sleep(std::time::Duration::from_millis(ms));
544	
545	        warm_loop(
546	            bench,
547	            WarmPass::Seconds {
548	                s: BLOCK_WARMUP_SECONDS,
549	                chunk: 1,
550	            },
551	            None,
552	            |_, n| n >= 1,
553	        );
554	        // Align batch boundaries to blocks: the flush moves the
555	        // batch clock past the sleep + warmup gap, so no batch
556	        // spans time the bench wasn't running.
557	        pipeline.flush();
558	
559	        let mut sum_ps: u128 = 0;
560	        let mut n: u64 = 0;
561	        match outer_override {
562	            Some(outer) => {
563	                // Distribute the remainder over the first blocks.
564	                let count = outer / blocks + u64::from(b < outer % blocks);
565	                for _ in 0..count {
566	                    sum_ps += u128::from(record_sample(bench, inner, pipeline, &mut dither));
567	                    n += 1;
568	                }
569	            }
570	            None => {
571	                let budget = target_seconds / blocks as f64;
572	                let block_start = std::time::Instant::now();
573	                loop {
574	                    sum_ps += u128::from(record_sample(bench, inner, pipeline, &mut dither));
575	                    n += 1;
576	                    if block_start.elapsed().as_secs_f64() >= budget {
577	                        break;
578	                    }
579	                }
580	            }
581	        }
582	        pipeline.flush();
583	        if n > 0 {
584	            means.push(sum_ps as f64 / n as f64 / PS_PER_NS);
585	        }
586	    }
