1	//! Layered configuration for defaults: built-in < XDG config file <
2	//! project-local file < CLI flags.
3	//!
4	//! - **XDG file** — `$XDG_CONFIG_HOME/iiac-perf/config.md` (or
5	//!   `.toml`), falling back to `$HOME/.config/iiac-perf/` when
6	//!   `XDG_CONFIG_HOME` is unset. The per-user home for defaults
7	//!   and pin profiles.
8	//! - **Project-local file** — `iiac-perf.md` (or `.toml`) in the
9	//!   current directory (no upward walk). Overrides the XDG file
10	//!   field-by-field; profiles merge by key.
11	//! - **CLI** — always wins, resolved in `main` after [`load`].
12	//!
13	//! Two carriers, one per directory. A `.md` config is a markdown
14	//! document whose `toml` fences, concatenated in document order,
15	//! are the config ([`crate::md_fence`]), so the prose between them
16	//! documents the file to its reader. `.md` is the recommended
17	//! form; plain `.toml` stays accepted. A directory holding both is
18	//! a hard error naming both paths, because the one the user edits
19	//! could otherwise be the one the loader ignores.
20	//!
21	//! A malformed or unreadable-but-present file is a hard error, so a
22	//! typo surfaces rather than silently reverting to built-ins.
23	
24	use std::collections::BTreeMap;
25	use std::path::{Path, PathBuf};
26	
27	use serde::Deserialize;
28	
29	use crate::bands::BandLabels;
30	use crate::md_fence::md_to_toml;
31	
32	/// Project-local override filenames (markdown carrier, TOML
33	/// carrier), looked up in the current directory only.
34	const LOCAL_MD: &str = "iiac-perf.md";
35	/// The project-local TOML carrier beside [`LOCAL_MD`].
36	const LOCAL_TOML: &str = "iiac-perf.toml";
37	
38	/// Inclusive upper bound on `decimals`, mirroring the
39	/// `--decimals` CLI `value_parser` range.
40	const DECIMALS_MAX: u8 = 3;
41	
42	/// The on-disk TOML shape, before validation. Scalars are
43	/// `Option` so an absent key stays absent (letting a lower layer
44	/// or built-in default show through); unknown keys are rejected
45	/// to catch typos.
46	#[derive(Debug, Default, Deserialize)]
47	#[serde(deny_unknown_fields)]
48	struct RawConfig {
49	    /// Default `--duration` seconds.
50	    duration: Option<f64>,
51	    /// Default `--band-labels` style, as its lowercase name.
52	    band_labels: Option<String>,
53	    /// Default `--decimals` count.
54	    decimals: Option<u8>,
55	    /// Default `--settle-time` seconds.
56	    settle_time: Option<f64>,
57	    /// Default `--warm-cap` seconds.
58	    warm_cap: Option<f64>,
59	    /// Named pin profiles: name -> `--pin` core spec.
60	    #[serde(default)]
61	    profiles: BTreeMap<String, String>,
62	    /// The declared `[freq]` steady state and pin target.
63	    freq: Option<FreqConfig>,
64	}
65	
66	/// The `[freq]` table: the box's declared steady state, and optionally a pin target.
67	///
68	/// This is what `restore-freq` converges to, written once by the user rather than remembered
69	/// from before a pin: a remembered state ratchets when run 2 starts while run 1's pin is live,
70	/// and a transient state file is a demonstrated failure mode in this repo. It normally lives in
71	/// the XDG config (`~/.config/iiac-perf/config.md`), the steady state being the box's rather
72	/// than the project's.
73	///
74	/// - `governor` is the one required key. `epp` and `boost` are required exactly when the box
75	///   exposes those knobs, which only [`crate::freqctl`] can check, so it is checked at use time
76	///   rather than here.
77	/// - Frequencies are MHz, the unit humans quote clocks in. The kHz conversion happens at the
78	///   sysfs boundary.
79	#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
80	#[serde(deny_unknown_fields)]
81	pub struct FreqConfig {
82	    /// Steady-state `scaling_governor` token, e.g. `powersave`.
83	    pub governor: String,
84	    /// Steady-state `energy_performance_preference` token. Required when the box has EPP,
85	    /// meaningless when it does not (rpi5-20cd exposes none).
86	    pub epp: Option<String>,
87	    /// Steady-state boost switch. Required when the box has a boost knob.
88	    pub boost: Option<bool>,
89	    /// Steady-state lower clamp (MHz). Absent means the hardware minimum.
90	    pub min_mhz: Option<u64>,
91	    /// Steady-state upper clamp (MHz). Absent means the hardware maximum.
92	    pub max_mhz: Option<u64>,
93	    /// Pin target (MHz) for `pin-freq` and `--pin-freq`. Absent means the discovered base
94	    /// clock.
95	    pub pin_mhz: Option<u64>,
96	}
97	
98	/// The merged, validated configuration handed to `main`.
99	///
100	/// Each scalar is `Option`: `None` means "no config opinion, use
101	/// the built-in default". Profiles are a flat name->spec map.
102	#[derive(Debug, Default, PartialEq)]
103	pub struct Config {
104	    /// Default `--duration` seconds, if configured.
105	    pub duration: Option<f64>,
106	    /// Default `--band-labels` style, if configured.
107	    pub band_labels: Option<BandLabels>,
108	    /// Default `--decimals` count, if configured.
109	    pub decimals: Option<u8>,
110	    /// Default `--settle-time` seconds, if configured.
111	    pub settle_time: Option<f64>,
112	    /// Default `--warm-cap` seconds, if configured.
113	    pub warm_cap: Option<f64>,
114	    /// Named pin profiles: name -> `--pin` core spec.
115	    pub profiles: BTreeMap<String, String>,
116	    /// The declared `[freq]` steady state and pin target, if configured.
117	    pub freq: Option<FreqConfig>,
118	}
119	
120	impl Config {
121	    /// Resolve a `--pin` spec against the configured profiles: a
122	    /// spec that names a profile expands to that profile's core
123	    /// spec; anything else is returned unchanged for
124	    /// [`crate::pin::parse_cores`] to parse as a raw core list.
125	    pub fn resolve_pin<'a>(&'a self, spec: &'a str) -> &'a str {
126	        self.profiles.get(spec).map(String::as_str).unwrap_or(spec)
127	    }
128	}
129	
130	/// The XDG config directory: `$XDG_CONFIG_HOME/iiac-perf`, falling
131	/// back to `$HOME/.config/iiac-perf`. `None` if neither env var is
132	/// set (e.g. a stripped-down service environment).
133	fn xdg_dir() -> Option<PathBuf> {
134	    let base = match std::env::var_os("XDG_CONFIG_HOME") {
135	        Some(x) if !x.is_empty() => PathBuf::from(x),
136	        _ => PathBuf::from(std::env::var_os("HOME")?).join(".config"),
137	    };
138	    Some(base.join("iiac-perf"))
139	}
140	
141	/// Resolve which carrier a layer holds: the `.md` file, the
142	/// `.toml` file, or neither (`Ok(None)`). Both present is a hard
143	/// error naming both paths: a silent precedence would leave the
144	/// user editing the ignored file with no effect and no clue.
145	fn resolve_carrier(md: PathBuf, toml: PathBuf) -> Result<Option<PathBuf>, String> {
146	    match (md.exists(), toml.exists()) {
147	        (true, true) => Err(format!(
148	            "both {} and {} exist: keep one (.md is the recommended carrier)",
149	            md.display(),
150	            toml.display()
151	        )),
152	        (true, false) => Ok(Some(md)),
153	        (false, true) => Ok(Some(toml)),
154	        (false, false) => Ok(None),
155	    }
156	}
157	
158	/// Load and merge the XDG and project-local config files. Returns
159	/// the merged [`Config`] plus the paths of the files that actually
160	/// existed (for the startup banner). Built-in-default `Config` when
161	/// no file exists; errors on a present-but-unreadable or malformed
162	/// file, and on a directory holding both carriers.
163	///
164	/// Layering: start from the XDG file, then overlay the local file
165	/// (scalars replace, profiles merge by key), so the nearer file
166	/// wins per field. The carrier rule is per directory, so the two
167	/// layers may use different carriers.
168	pub fn load() -> Result<(Config, Vec<PathBuf>), String> {
169	    let mut raw = RawConfig::default();
170	    let mut loaded = Vec::new();
171	    if let Some(dir) = xdg_dir()
172	        && let Some(path) = resolve_carrier(dir.join("config.md"), dir.join("config.toml"))?
173	    {
174	        overlay(&mut raw, &path)?;
175	        loaded.push(path);
176	    }
177	    if let Some(path) = resolve_carrier(PathBuf::from(LOCAL_MD), PathBuf::from(LOCAL_TOML))? {
178	        overlay(&mut raw, &path)?;
179	        loaded.push(path);
180	    }
181	    Ok((validate(raw)?, loaded))
182	}
183	
184	/// Read one config file (either carrier) and overlay it onto
185	/// `base`: each present scalar replaces `base`'s, and profiles are
186	/// merged by key (the file's entries win). A `.md` path runs
187	/// through the fence filter first; anything else parses as plain
188	/// TOML.
189	fn overlay(base: &mut RawConfig, path: &Path) -> Result<(), String> {
190	    let text =
191	        std::fs::read_to_string(path).map_err(|e| format!("reading {}: {e}", path.display()))?;
192	    let text = if path.extension().is_some_and(|e| e == "md") {
193	        md_to_toml(&text).map_err(|e| format!("{}: {e}", path.display()))?
194	    } else {
195	        text
196	    };
197	    let over: RawConfig =
198	        toml::from_str(&text).map_err(|e| format!("parsing {}: {e}", path.display()))?;
199	    if over.duration.is_some() {
200	        base.duration = over.duration;
201	    }
202	    if over.band_labels.is_some() {
203	        base.band_labels = over.band_labels;
204	    }
205	    if over.decimals.is_some() {
206	        base.decimals = over.decimals;
207	    }
208	    if over.settle_time.is_some() {
209	        base.settle_time = over.settle_time;
210	    }
211	    if over.warm_cap.is_some() {
212	        base.warm_cap = over.warm_cap;
213	    }
214	    // The whole [freq] table replaces, never field-merges: the steady state is one declaration
215	    // of one box's state, and half of one file's declaration on top of half of another's would
216	    // be a state nobody declared.
217	    if over.freq.is_some() {
218	        base.freq = over.freq;
219	    }
220	    base.profiles.extend(over.profiles);
221	    Ok(())
222	}
223	
224	/// Validate a merged [`RawConfig`] into a [`Config`]: map the
225	/// `band_labels` name to the enum, range-check `decimals`, and
226	/// reject a negative `settle_time`.
227	fn validate(raw: RawConfig) -> Result<Config, String> {
228	    let band_labels = match raw.band_labels {
229	        None => None,
230	        Some(s) => Some(match s.as_str() {
231	            "zpn" => BandLabels::Zpn,
232	            "frac" => BandLabels::Frac,
233	            "both" => BandLabels::Both,
234	            other => {
235	                return Err(format!(
236	                    "band_labels: {other:?} is not one of zpn, frac, both"
237	                ));
238	            }
239	        }),
240	    };
241	    if let Some(d) = raw.decimals
242	        && d > DECIMALS_MAX
243	    {
244	        return Err(format!(
245	            "decimals: {d} exceeds the maximum of {DECIMALS_MAX}"
246	        ));
247	    }
248	    if let Some(t) = raw.settle_time
249	        && t < 0.0
250	    {
251	        return Err(format!("settle_time: {t} is negative"));
252	    }
253	    if let Some(t) = raw.warm_cap
254	        && t < 0.0
255	    {
256	        return Err(format!("warm_cap: {t} is negative"));
257	    }
258	    if let Some(f) = &raw.freq {
259	        validate_freq(f)?;
260	    }
261	    Ok(Config {
262	        duration: raw.duration,
263	        band_labels,
264	        decimals: raw.decimals,
265	        settle_time: raw.settle_time,
266	        warm_cap: raw.warm_cap,
267	        profiles: raw.profiles,
268	        freq: raw.freq,
269	    })
270	}
271	
272	/// Validate a `[freq]` table's box-independent facts: frequencies are nonzero and the clamps
273	/// are ordered. Whether the tokens and values fit the actual box is `freqctl`'s job at use
274	/// time.
275	fn validate_freq(f: &FreqConfig) -> Result<(), String> {
276	    if f.governor.is_empty() {
277	        return Err("freq.governor: empty".to_string());
278	    }
279	    for (name, mhz) in [
280	        ("min_mhz", f.min_mhz),
281	        ("max_mhz", f.max_mhz),
282	        ("pin_mhz", f.pin_mhz),
283	    ] {
284	        if mhz == Some(0) {
285	            return Err(format!("freq.{name}: 0 is not a frequency"));
286	        }
287	    }
288	    if let (Some(min), Some(max)) = (f.min_mhz, f.max_mhz)
289	        && min > max
290	    {
291	        return Err(format!("freq: min_mhz {min} exceeds max_mhz {max}"));
292	    }
293	    Ok(())
294	}
295	
296	#[cfg(test)]
297	mod tests {
298	    use super::*;
299	
300	    fn parse(text: &str) -> Result<Config, String> {
301	        validate(toml::from_str(text).map_err(|e| e.to_string())?)
302	    }
303	
304	    #[test]
305	    fn empty_is_all_none() {
306	        assert_eq!(parse("").unwrap(), Config::default());
307	    }
308	
309	    #[test]
