356	
357	    #[test]
358	    fn freq_table_parses() {
359	        let c = parse(
360	            "[freq]\ngovernor = \"powersave\"\nepp = \"balance_performance\"\n\
361	             boost = true\npin_mhz = 3800\n",
362	        )
363	        .unwrap();
364	        let f = c.freq.unwrap();
365	        assert_eq!(f.governor, "powersave");
366	        assert_eq!(f.epp.as_deref(), Some("balance_performance"));
367	        assert_eq!(f.boost, Some(true));
368	        assert_eq!(f.min_mhz, None);
369	        assert_eq!(f.pin_mhz, Some(3800));
370	    }
371	
372	    #[test]
373	    fn freq_table_requires_governor() {
374	        assert!(parse("[freq]\nboost = true\n").is_err());
375	    }
376	
377	    #[test]
378	    fn freq_rejects_zero_and_inverted_clamps() {
379	        assert!(parse("[freq]\ngovernor = \"g\"\npin_mhz = 0\n").is_err());
380	        assert!(parse("[freq]\ngovernor = \"g\"\nmin_mhz = 4000\nmax_mhz = 3000\n").is_err());
381	        assert!(parse("[freq]\ngovernor = \"g\"\nmin_mhz = 550\nmax_mhz = 5573\n").is_ok());
382	    }
383	
384	    #[test]
385	    fn freq_table_replaces_whole_never_field_merges() {
386	        let dir = scratch("freq-replace");
387	        let xdg = dir.join("config.toml");
388	        let local = dir.join("local.toml");
389	        std::fs::write(
390	            &xdg,
391	            "[freq]\ngovernor = \"powersave\"\nepp = \"balance_performance\"\nboost = true\n",
392	        )
393	        .unwrap();
394	        std::fs::write(&local, "[freq]\ngovernor = \"schedutil\"\n").unwrap();
395	        let mut raw = RawConfig::default();
396	        overlay(&mut raw, &xdg).unwrap();
397	        overlay(&mut raw, &local).unwrap();
398	        let f = validate(raw).unwrap().freq.unwrap();
399	        // The nearer file's whole table wins: no epp/boost leak through from the XDG layer.
400	        assert_eq!(f.governor, "schedutil");
401	        assert_eq!(f.epp, None);
402	        assert_eq!(f.boost, None);
