406	    /// A fresh scratch directory under the test temp root, named
407	    /// per test so parallel tests never share one.
408	    fn scratch(name: &str) -> PathBuf {
409	        let dir = std::env::temp_dir()
410	            .join("iiac-perf-config-tests")
411	            .join(name);
412	        std::fs::remove_dir_all(&dir).ok();
413	        std::fs::create_dir_all(&dir).unwrap();
