440	        let mut raw = RawConfig::default();
441	        let err = overlay(&mut raw, &path).unwrap_err();
442	        assert!(err.contains("config.md"), "unexpected error: {err}");
443	        assert!(err.contains("unclosed fence"), "unexpected error: {err}");
444	        std::fs::remove_dir_all(&dir).ok();
445	    }
446	
447	    #[test]
448	    fn resolve_prefers_lone_carrier_and_rejects_both() {
449	        let dir = scratch("resolve");
450	        let md = dir.join("config.md");
451	        let toml = dir.join("config.toml");
452	        let resolve = |md: &PathBuf, toml: &PathBuf| resolve_carrier(md.clone(), toml.clone());
453	
454	        assert_eq!(resolve(&md, &toml).unwrap(), None);
455	
456	        std::fs::write(&toml, "duration = 1.0\n").unwrap();
457	        assert_eq!(resolve(&md, &toml).unwrap(), Some(toml.clone()));
458	
459	        std::fs::write(&md, "```toml\nduration = 2.0\n```\n").unwrap();
460	        let err = resolve(&md, &toml).unwrap_err();
461	        assert!(err.contains("config.md"), "unexpected error: {err}");
462	        assert!(err.contains("config.toml"), "unexpected error: {err}");
463	
464	        std::fs::remove_file(&toml).unwrap();
465	        assert_eq!(resolve(&md, &toml).unwrap(), Some(md.clone()));
466	        std::fs::remove_dir_all(&dir).ok();
467	    }
