/// stats when they apply — `suspended_s` comes from
/// [`crate::harness::run_adaptive`] (see [`warn_invalid`]).
pub fn print_report(name: &str, out: &RunOutput, cfg: &RunCfg) {
    let hist = &out.hist;
    let outer = out.outer;
    let inner = out.inner;
    let duration_s = out.duration_s;
    let suspended_s = out.suspended_s;
    let block_stats = out.block_stats.as_ref();
    // Header line: bench name + logfmt-style metadata.
    let total = outer * inner;
    let blocks_meta = match block_stats {
        Some(b) => format!(" blocks={}", b.blocks),
        None => String::new(),
    };
    let batches_meta = format!(" batches={}", out.batches.len());
    // The warm cell is this run's total spend over its total
    // allowance: settle budget (when this run ran the process
    // warm) plus the cap.
    println!(
        "{name} [duration={:.1}s warm={:.2}/{:.1}s outer={} inner={} calls={}{blocks_meta}{batches_meta} labels={}]:",
        duration_s,
        out.warm_used_s,
        out.warm_budget_s,
        fmt_commas(outer),
        inner,
        fmt_commas(total),
        cfg.band_labels.as_str(),
    );

    let bounds = bands::boundaries();

    // Trim anchor: bands at or above the n2 (p99) boundary are
    // the "tail" — excluded from the trimmed stats no matter how
    // many finer tail bands subdivide them.
    #[allow(clippy::unwrap_used)]
    // OK: boundaries() always emits n2 (N_DEPTH >= 2)
    let trim_bands = bounds.iter().position(|b| b.zpn == "n2").unwrap();

    let n_bands = bounds.len() - 1;
    let sample_count = hist.len();

    // Accumulate per-band stats by walking recorded histogram buckets.
    // Each bucket is assigned to the band containing its midpoint rank.
    let mut band_first = vec![u64::MAX; n_bands];
    let mut band_last = vec![0u64; n_bands];
    let mut band_count = vec![0u64; n_bands];
    let mut band_sum = vec![0u128; n_bands];

    let mut cumulative = 0u64;
    for iv in hist.iter_recorded() {
        let value = iv.value_iterated_to();
        let count = iv.count_at_value();
        let mid_rank = (cumulative as f64 + count as f64 / 2.0) / sample_count as f64;
        let idx = band_index(mid_rank, &bounds);
        band_first[idx] = band_first[idx].min(value);
        band_last[idx] = band_last[idx].max(value);
        band_count[idx] += count;
        band_sum[idx] += value as u128 * count as u128;

        if idx < trim_bands {
            let diff = value as f64 / PS_PER_NS - trim_mean;
            trim_var_sum += diff * diff * count as f64;
            trim_var_count += count;
        }
        cum += count;
    }
    let trim_stdev = if trim_var_count > 1 {
        (trim_var_sum / trim_var_count as f64).sqrt()
    } else {
        0.0
    };

    Some((
        fmt_commas_f64(trim_mean, cfg.decimals),
        fmt_commas_f64(trim_stdev, cfg.decimals),
    ))
} else {
    None
};

// Block-replication summary strings, rendered before the
// width pass like the other summary lines.
let block_strs = block_stats.map(|b| {
    (
        fmt_commas_f64(b.mean_ns, cfg.decimals),
        fmt_commas_f64(b.ci95_ns, cfg.decimals),
        fmt_commas_f64(b.lsc_ns, cfg.decimals),
    )
});

// The clock's per-sample quantum, rendered next to the spread
// rows because that is where it is needed: it says whether
// those rows describe the workload or the lattice. At least 3
// decimals regardless of `--decimals`, since a fine quantum
// renders as `0.0` at the report's default precision and zero
// is the one value it must never claim.
let quantum_str = fmt_commas_f64(
    quantum_ns(ticks::ticks_per_ns(), inner),
    cfg.decimals.max(3),
);

// Column widths from rendered strings: band rows and the
// summary lines that print in the mean column.
let label_cols = rows
    .iter()
    .map(|r| display_cols(&r.label))
    .fold(display_cols(&stdev_trim_label), usize::max);
let first_cols = rows
    .iter()
    .map(|r| display_cols(&r.first))
    .fold(0, usize::max);
let last_cols = rows
    .iter()
    .map(|r| display_cols(&r.last))
    .fold(0, usize::max);
let range_cols = rows
    .iter()
    .map(|r| display_cols(&r.range))
    .fold(0, usize::max);
let count_cols = rows
    .iter()
    .map(|r| display_cols(&r.count))
    .fold(0, usize::max);
// The mean column aligns on the decimal point rather than on
// its last character, so each side is measured separately:
// `quantum` prints at least three decimals while every other
// row follows `--decimals`, and a shared right edge would
// stagger the points (see [`decimal_align`]).
let mean_values: Vec<&str> = rows
    .iter()
    .map(|r| r.mean.as_str())
    .chain([
        hist_mean_str.as_str(),
        hist_stdev_str.as_str(),
        quantum_str.as_str(),
    ])
    .chain(trim.iter().flat_map(|(m, s)| [m.as_str(), s.as_str()]))
    .chain(
        block_strs
            .iter()
            .flat_map(|(m, c, l)| [m.as_str(), c.as_str(), l.as_str()]),
    )
    .collect();
let mean_int_cols = mean_values
    .iter()
    .map(|s| display_cols(split_decimal(s).0))
    .fold(0, usize::max);
let mean_frac_cols = mean_values
    .iter()
    .map(|s| display_cols(split_decimal(s).1))
    .fold(0, usize::max);
let mean_cols = mean_int_cols
    + if mean_frac_cols > 0 {
        mean_frac_cols + 1
    } else {
        0
    };

const INDENT: &str = "  ";
const GAP: &str = "    ";

// Header row. Each label right-justifies to the last
// character of its column's ` ns` unit; `count` is unitless
// and right-justifies to its digits.
const UNIT: usize = " ns".len();
let first_col = INDENT.len() + label_cols + 1 + first_cols + UNIT;
let last_gap = GAP.len() + last_cols + UNIT;
let range_gap = GAP.len() + range_cols + UNIT;
let count_gap = GAP.len() + count_cols;
let mean_gap = GAP.len() + mean_cols + UNIT;
println!(
    "{:>first_col$}{:>last_gap$}{:>range_gap$}{:>count_gap$}{:>mean_gap$}",
    "first", "last", "range", "count", "mean",
);

for r in &rows {
    println!(
        "{INDENT}{:<label_cols$} {:>first_cols$} ns{GAP}{:>last_cols$} ns{GAP}{:>range_cols$} ns{GAP}{:>count_cols$}{GAP}{} ns",
        r.label,
        r.first,
        r.last,
        r.range,
        r.count,
        decimal_align(&r.mean, mean_int_cols, mean_frac_cols),
    );
}

// Whole-histogram summary. Aligned to the mean column.
let skip = first_cols
    + " ns".len()
    + GAP.len()
    + last_cols
    + " ns".len()
    + GAP.len()
    + range_cols
    + " ns".len()
    + GAP.len()
    + count_cols;
let cell = |s: &str| decimal_align(s, mean_int_cols, mean_frac_cols);
println!(
    "{INDENT}{:<label_cols$} {:>skip$}{GAP}{} ns",
    "mean",
    "",
    cell(&hist_mean_str),
);
println!(
    "{INDENT}{:<label_cols$} {:>skip$}{GAP}{} ns",
    "stdev",
    "",
    cell(&hist_stdev_str),
);

if let Some((trim_mean_str, trim_stdev_str)) = &trim {
    println!(
        "{INDENT}{:<label_cols$} {:>skip$}{GAP}{} ns",
        mean_trim_label,
        "",
        cell(trim_mean_str),
    );
    println!(
        "{INDENT}{:<label_cols$} {:>skip$}{GAP}{} ns",
        stdev_trim_label,
        "",
        cell(trim_stdev_str),
    );
}
println!(
    "{INDENT}{:<label_cols$} {:>skip$}{GAP}{} ns",
    "quantum",
    "",
    cell(&quantum_str),
);
if let Some((block_mean_str, block_ci_str, block_lsc_str)) = &block_strs {
    println!(
        "{INDENT}{:<label_cols$} {:>skip$}{GAP}{} ns",
        "mean blocks",
        "",
        cell(block_mean_str),
    );
    println!(
        "{INDENT}{:<label_cols$} {:>skip$}{GAP}{} ns",
        "CI95",
        "",
        cell(block_ci_str),
    );
    println!(
        "{INDENT}{:<label_cols$} {:>skip$}{GAP}{} ns",
        "LSC",
        "",
        cell(block_lsc_str),
    );
}
// The grade block: one header over three rows, `env` grading
// the *box* (two stretches: did warmup end settled, did the
// bench stretch stay settled) above `run` grading *these*
// numbers from the run's own batches. Each row's `worst` is
// its own composite (worst signal wins), printed beside its
// causes; a blank cell means the signal does not apply to
// that row, which is the env/run signal mapping made

//! Per-run NDJSON records: the `--record` side channel that outlives the session.
//!
//! The report prints and is gone, so no run's numbers survive the terminal that showed them.
//! This module appends one self-describing JSON object per finished harness run, alongside the
//! unchanged display, so a run can be re-analysed without its session.
//!
//! - **One object per bench result**, not per process: `all` emits one record per bench, each
//!   carrying the host / policy / clock stamp of its own run.
//! - **NDJSON, one object per line**: `jq -s .` makes an array on demand, an interrupted run
//!   still parses, and per-run files concatenate with `cat`.
//! - **The open is append-and-create, never truncate**, in both path modes: the no-truncate
//!   invariant is what protects existing evidence, whoever chose the file name.
//! - **The record documents its own fields**: [`FIELD_DOCS`] is the dictionary the
//!   `describe-record` command prints, and a test fails on any record key with no entry.
//! - **Absent is not zero**: every field a box may not expose serializes as `null` rather than
//!   a default, so the key set is identical in every record.

use std::collections::BTreeMap;
use std::io::Write;
use std::path::{Path, PathBuf};

use serde::Serialize;

use crate::freq::{self, PolicyField};
use crate::gauge::Settle;
use crate::harness::{PS_PER_NS, RunCfg, RunOutput, WarmExit};

/// Layout version stamped into every record, bumped on any change to a field's name, unit, or
/// meaning, so a dictionary printed by today's binary can be checked against a record written
/// by an older one.
pub const SCHEMA_VERSION: u32 = 1;

/// The fixed quantile ladder (percentages), identical in every record. Fixed rather than the
/// report's populated bands, whose labels move with the data: a constant ladder is what makes
/// an A/B estimator question answerable after the fact, cheap now and impossible to backfill.
pub const QUANTILE_PCTS: [f64; 13] = [
    0.01, 0.1, 1.0, 5.0, 10.0, 25.0, 50.0, 75.0, 90.0, 95.0, 99.0, 99.9, 99.99,
];

/// Where records go: resolved once from the `--record` path's shape.
#[derive(Debug, PartialEq, Eq)]
enum Target {
    /// One file per run inside this directory, named `<ts>-<host>-<bench>.ndjson`, so a rerun
    /// can never clobber a run's evidence (a fixed name is exactly what killed the powersave
    /// series).
    Dir(PathBuf),
    /// Every record appends to this one file.
    File(PathBuf),
}

/// The resolved `--record` sink: target, verbatim tags, and the host stamp, built once at
/// startup so a bad path fails before any bench spends minutes measuring.
#[derive(Debug)]
pub struct Recorder {
    target: Target,
    tags: BTreeMap<String, String>,
    host: String,
}

/// One NDJSON record: everything a re-analysis needs without the session that produced it.
/// Field meanings live in [`FIELD_DOCS`], the single dictionary a test keeps honest.
#[derive(Serialize)]
struct Record<'a> {
    schema_version: u32,
    version: &'static str,
    t_start: String,
    utc_offset_s: Option<i64>,
    host: &'a str,
    pid: u32,
    run_index: u32,
    bench: &'a str,
    tags: &'a BTreeMap<String, String>,
    pin_cpus: &'a [usize],
    duration_s: f64,
    suspended_s: f64,
    warm_exit: &'static str,
    warm_used_s: f64,
    warm_budget_s: f64,
    settle_s: Option<f64>,
    settle_ghz: Option<f64>,
    samples: u64,
    inner: u64,
    calls: u64,
    min_ns: f64,
    mean_ns: f64,
    stdev_ns: f64,
    max_ns: f64,
    quantile_pcts: &'static [f64],
    quantile_ns: Vec<f64>,
    blocks: Option<u64>,
    block_mean_ns: Option<&'a [f64]>,
    block_ci95_ns: Option<f64>,
    block_lsc_ns: Option<f64>,
    clock_t_ns: Vec<u64>,
    clock_cpu: Vec<usize>,
    clock_khz: Vec<u64>,
    driver: Option<&'a PolicyField>,
    governor: Option<&'a PolicyField>,
    epp: Option<&'a PolicyField>,
    boost: Option<&'a PolicyField>,
    scaling_min_freq: Option<&'a PolicyField>,
    scaling_max_freq: Option<&'a PolicyField>,
}

/// One field's dictionary entry: name, unit, one-line meaning.
