    }

    #[test]
    fn target_mode_follows_the_path_shape() {
        // A trailing slash is dir mode whether or not the directory exists yet.
        assert_eq!(
            resolve_target(Path::new("no/such/dir/")),
            Target::Dir(PathBuf::from("no/such/dir/"))
        );
