1	//! Explicit CPU-frequency control: the `read-freq` / `pin-freq` / `restore-freq` command words
2	//! and the `--pin-freq` run guard.
3	//!
4	//! [`crate::freq`] reads and never writes. This module is the one place the harness mutates the
5	//! box, and the reasons mutation used to be banned outright (root, global, persistent) survive
6	//! as its design constraints:
7	//!
8	//! - mutation happens only on an explicit command word or flag, never as a side effect
9	//! - a pinned run restores on every catchable exit path: normal return and panic via the
10	//!   guard's `Drop`, SIGINT and SIGTERM via a pre-rendered async-signal-safe handler
11	//! - restore converges to a steady state the user *declared* in the config's `[freq]` section,
12	//!   never to a remembered one. A remembered state ratchets on back-to-back runs (run 2
13	//!   "restores" run 1's pin), and transient state files are a demonstrated failure mode in this
14	//!   repo. Declared-state convergence is idempotent from any starting point, which is also the
15	//!   whole recovery story after SIGKILL or power loss: run `restore-freq`, nothing saved to
16	//!   find
17	//!
18	//! Writes are staged as ordered **plans** of (path, token) pairs because cpufreq rejects
19	//! `min > max`: every clamp move goes floor-first (min to the hardware floor, then max, then
20	//! min), so each intermediate write is valid from any starting state. A pin is `min = max` at
21	//! the target with boost off, and the load-independent default target is the base clock
22	//! ([`freq::base_clock`]), the manufacturer's guaranteed all-core sustained frequency.
23	
24	use std::ffi::CString;
25	use std::sync::OnceLock;
26	
27	use crate::config::FreqConfig;
28	use crate::freq;
29	
30	/// An ordered list of sysfs writes: (absolute path, token). Order is load-bearing, see the
31	/// module doc's floor-first rule.
32	type Plan = Vec<(String, String)>;
33	
34	/// The kernel's single boost knob when the driver has no per-CPU `boost` files.
35	const GLOBAL_BOOST: &str = "/sys/devices/system/cpu/cpufreq/boost";
36	
37	/// Path of one per-CPU cpufreq knob.
38	fn knob(cpu: usize, name: &str) -> String {
39	    format!("/sys/devices/system/cpu/cpu{cpu}/cpufreq/{name}")
40	}
41	
42	/// Which boost control the box exposes, decided once at capability read.
43	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
44	enum BoostKnob {
45	    /// No boost control at all (rpi5-20cd).
46	    None,
47	    /// Per-CPU `cpufreq/boost` files.
48	    PerCpu,
49	    /// The single global `cpufreq/boost` file.
50	    Global,
51	}
52	
53	/// One CPU's write targets and validation data.
54	#[derive(Debug, Clone, PartialEq, Eq)]
55	struct CpuCaps {
56	    /// The logical CPU number.
57	    cpu: usize,
58	    /// `cpuinfo_min_freq` (kHz): the hardware floor, and the staging value for clamp moves.
59	    hw_min_khz: u64,
60	    /// `cpuinfo_max_freq` (kHz): the hardware ceiling.
61	    hw_max_khz: u64,
62	    /// Discrete `scaling_available_frequencies` (kHz) where the driver lists them, `None` on
63	    /// continuous-range drivers (amd-pstate, intel_pstate).
64	    avail_khz: Option<Vec<u64>>,
65	}
66	
67	/// What the box exposes, read once per command: write targets plus the data that validates a
68	/// declared state against reality.
69	#[derive(Debug, Clone, PartialEq, Eq)]
70	struct BoxCaps {
71	    /// Per-CPU capabilities, ascending by CPU.
72	    cpus: Vec<CpuCaps>,
73	    /// Whether `energy_performance_preference` exists (amd-pstate-epp yes, rpi5-20cd no).
74	    has_epp: bool,
75	    /// `scaling_available_governors`, when readable, for validating the declared governor.
76	    governors: Option<Vec<String>>,
77	    /// `energy_performance_available_preferences`, when readable.
78	    epp_prefs: Option<Vec<String>>,
79	    /// Which boost control exists.
80	    boost: BoostKnob,
81	}
82	
83	/// Read the box's capabilities from sysfs. Errors when there is no cpufreq to control (a VM,
84	/// typically), naming what is missing.
85	fn read_caps() -> Result<BoxCaps, String> {
86	    let cpu_ids = freq::cpus();
87	    let Some(&first) = cpu_ids.first() else {
88	        return Err("no CPUs under /sys/devices/system/cpu".to_string());
89	    };
90	    let mut cpus = Vec::with_capacity(cpu_ids.len());
91	    for cpu in cpu_ids {
92	        let (Some(hw_min_khz), Some(hw_max_khz)) = (
93	            freq::read_khz(cpu, "cpuinfo_min_freq"),
94	            freq::read_khz(cpu, "cpuinfo_max_freq"),
95	        ) else {
96	            return Err(format!(
97	                "cpu{cpu} exposes no cpufreq range (cpuinfo_min_freq/cpuinfo_max_freq): \
98	                 nothing to control"
99	            ));
100	        };
101	        cpus.push(CpuCaps {
102	            cpu,
103	            hw_min_khz,
104	            hw_max_khz,
105	            avail_khz: freq::available_khz(cpu),
106	        });
107	    }
108	    let boost = if freq::read_token(first, "boost").is_some() {
109	        BoostKnob::PerCpu
110	    } else if std::path::Path::new(GLOBAL_BOOST).exists() {
111	        BoostKnob::Global
112	    } else {
113	        BoostKnob::None
114	    };
115	    Ok(BoxCaps {
116	        cpus,
117	        has_epp: freq::read_token(first, "energy_performance_preference").is_some(),
118	        governors: token_list(first, "scaling_available_governors"),
119	        epp_prefs: token_list(first, "energy_performance_available_preferences"),
120	        boost,
121	    })
122	}
123	
124	/// One whitespace-separated token-list file for `cpu`, `None` when absent.
125	fn token_list(cpu: usize, name: &str) -> Option<Vec<String>> {
126	    let text = freq::read_token(cpu, name)?;
127	    Some(text.split_whitespace().map(str::to_string).collect())
128	}
129	
130	/// The declared steady state, validated against the box: what `restore-freq` converges to.
131	#[derive(Debug, Clone, PartialEq, Eq)]
132	struct Steady {
133	    /// The declared governor token.
134	    governor: String,
135	    /// The declared EPP token, present exactly when the box has EPP.
136	    epp: Option<String>,
137	    /// The declared boost switch, present exactly when the box has a boost knob.
138	    boost: Option<bool>,
139	    /// Declared lower clamp (kHz), `None` meaning each CPU's hardware floor.
140	    min_khz: Option<u64>,
141	    /// Declared upper clamp (kHz), `None` meaning each CPU's hardware ceiling.
142	    max_khz: Option<u64>,
143	}
144	
145	/// The refusal printed when no `[freq]` table is declared: pinning without a declared way home
146	/// is exactly the failure mode this design exists against.
147	fn no_steady_state() -> String {
148	    "no [freq] steady state is declared, so a pin would have no way home.\n\
149	     Add a [freq] section to the config, usually ~/.config/iiac-perf/config.md (in a toml \
150	     fence).\n\
151	     `iiac-perf read-freq --as-config` prints the current state in that form, ready to paste.\n\
152	     Under sudo, $HOME may be root's. The project-local ./iiac-perf.md works there too."
153	        .to_string()
154	}
155	
156	/// Validate the declared `[freq]` table against the box's capabilities.
157	///
158	/// The box-dependent completeness rule lives here: a knob the box exposes must be declared
159	/// (restoring around it would silently leave a pin's residue), and a knob the box lacks must
160	/// not be (the declaration would be fiction).
161	fn resolve_steady(cfg: Option<&FreqConfig>, caps: &BoxCaps) -> Result<Steady, String> {
162	    let Some(cfg) = cfg else {
163	        return Err(no_steady_state());
164	    };
165	    if let Some(governors) = &caps.governors
166	        && !governors.contains(&cfg.governor)
167	    {
168	        return Err(format!(
169	            "freq.governor {:?} is not available on this box (available: {})",
170	            cfg.governor,
171	            governors.join(", ")
172	        ));
173	    }
174	    match (caps.has_epp, &cfg.epp) {
175	        (true, None) => {
176	            let hint = match &caps.epp_prefs {
177	                Some(p) => format!(" (available: {})", p.join(", ")),
178	                None => String::new(),
179	            };
180	            return Err(format!(
181	                "this box exposes energy_performance_preference: declare freq.epp{hint}"
182	            ));
183	        }
184	        (false, Some(_)) => {
185	            return Err("freq.epp is declared but this box exposes no \
186	                        energy_performance_preference"
187	                .to_string());
188	        }
189	        (true, Some(epp)) => {
190	            if let Some(prefs) = &caps.epp_prefs
191	                && !prefs.contains(epp)
192	            {
193	                return Err(format!(
194	                    "freq.epp {:?} is not available on this box (available: {})",
195	                    epp,
196	                    prefs.join(", ")
197	                ));
198	            }
199	        }
200	        (false, None) => {}
201	    }
202	    match (caps.boost, cfg.boost) {
203	        (BoostKnob::None, Some(_)) => {
204	            return Err("freq.boost is declared but this box exposes no boost control".to_string());
205	        }
206	        (BoostKnob::PerCpu | BoostKnob::Global, None) => {
207	            return Err("this box exposes a boost control: declare freq.boost".to_string());
208	        }
209	        _ => {}
210	    }
211	    let min_khz = cfg.min_mhz.map(|m| m * 1000);
212	    let max_khz = cfg.max_mhz.map(|m| m * 1000);
213	    for c in &caps.cpus {
214	        for (name, khz) in [("min_mhz", min_khz), ("max_mhz", max_khz)] {
215	            if let Some(khz) = khz
216	                && !(c.hw_min_khz..=c.hw_max_khz).contains(&khz)
217	            {
218	                return Err(format!(
219	                    "freq.{name} {} MHz is outside cpu{}'s range {}-{} MHz",
220	                    khz / 1000,
221	                    c.cpu,
222	                    c.hw_min_khz / 1000,
223	                    c.hw_max_khz / 1000
224	                ));
225	            }
226	        }
227	    }
228	    Ok(Steady {
229	        governor: cfg.governor.clone(),
230	        epp: cfg.epp.clone(),
231	        boost: cfg.boost,
232	        min_khz,
233	        max_khz,
234	    })
235	}
236	
237	/// The boost writes for `enabled`, empty when the box has no knob.
238	fn boost_writes(caps: &BoxCaps, enabled: bool) -> Plan {
239	    let token = if enabled { "1" } else { "0" };
240	    match caps.boost {
241	        BoostKnob::None => Vec::new(),
242	        BoostKnob::Global => vec![(GLOBAL_BOOST.to_string(), token.to_string())],
243	        BoostKnob::PerCpu => caps
244	            .cpus
245	            .iter()
246	            .map(|c| (knob(c.cpu, "boost"), token.to_string()))
247	            .collect(),
248	    }
249	}
250	
251	/// The clamp writes taking one CPU from any state to `[min_khz, max_khz]`, floor-first so every
252	/// intermediate write is valid (see the module doc).
253	fn clamp_writes(c: &CpuCaps, min_khz: u64, max_khz: u64) -> Plan {
254	    vec![
255	        (knob(c.cpu, "scaling_min_freq"), c.hw_min_khz.to_string()),
256	        (knob(c.cpu, "scaling_max_freq"), max_khz.to_string()),
257	        (knob(c.cpu, "scaling_min_freq"), min_khz.to_string()),
258	    ]
259	}
260	
261	/// The plan converging the box to `steady`: governor and EPP first (amd-pstate ties the legal
262	/// EPP values to the governor), then boost, then the clamps.
263	fn restore_plan(steady: &Steady, caps: &BoxCaps) -> Plan {
264	    let mut plan = Plan::new();
265	    for c in &caps.cpus {
266	        plan.push((knob(c.cpu, "scaling_governor"), steady.governor.clone()));
267	        if let Some(epp) = &steady.epp {
268	            plan.push((knob(c.cpu, "energy_performance_preference"), epp.clone()));
269	        }
270	    }
271	    if let Some(enabled) = steady.boost {
272	        plan.extend(boost_writes(caps, enabled));
273	    }
274	    for c in &caps.cpus {
275	        let min_khz = match steady.min_khz {
276	            Some(k) => k,
277	            None => c.hw_min_khz,
278	        };
279	        let max_khz = match steady.max_khz {
280	            Some(k) => k,
281	            None => c.hw_max_khz,
282	        };
283	        plan.extend(clamp_writes(c, min_khz, max_khz));
284	    }
285	    plan
286	}
287	
288	/// The plan pinning every CPU at `khz`: boost off, then `min = max = khz`. Errors when the
289	/// target does not fit a CPU, naming that CPU's valid values.
290	fn pin_plan(khz: u64, caps: &BoxCaps) -> Result<Plan, String> {
291	    for c in &caps.cpus {
292	        if let Some(avail) = &c.avail_khz {
293	            if !avail.contains(&khz) {
294	                let mhz: Vec<String> = avail.iter().map(|k| (k / 1000).to_string()).collect();
295	                return Err(format!(
296	                    "{} MHz is not one of cpu{}'s discrete frequencies ({} MHz)",
297	                    khz / 1000,
298	                    c.cpu,
299	                    mhz.join(", ")
300	                ));
301	            }
302	        } else if !(c.hw_min_khz..=c.hw_max_khz).contains(&khz) {
303	            return Err(format!(
304	                "{} MHz is outside cpu{}'s range {}-{} MHz",
305	                khz / 1000,
306	                c.cpu,
307	                c.hw_min_khz / 1000,
308	                c.hw_max_khz / 1000
309	            ));
310	        }
311	    }
312	    let mut plan = boost_writes(caps, false);
313	    for c in &caps.cpus {
314	        plan.extend(clamp_writes(c, khz, khz));
315	    }
316	    Ok(plan)
317	}
318	
319	/// Resolve the pin target: the command line, else the config's `pin_mhz`, else the discovered
320	/// base clock. Returns the kHz value and a human phrase saying where it came from.
321	fn resolve_pin(cfg: Option<&FreqConfig>, cli_mhz: Option<u64>) -> Result<(u64, String), String> {
322	    if let Some(mhz) = cli_mhz {
323	        if mhz == 0 {
324	            return Err("0 is not a frequency".to_string());
325	        }
326	        return Ok((mhz * 1000, "given on the command line".to_string()));
327	    }
328	    if let Some(mhz) = cfg.and_then(|f| f.pin_mhz) {
329	        return Ok((mhz * 1000, "config pin_mhz".to_string()));
330	    }
331	    match freq::base_clock() {
332	        Some(b) => Ok((b.khz, format!("base clock from {}", b.source))),
333	        None => Err(
334	            "no pin target: none given, no [freq] pin_mhz configured, and no base \
335	                     clock discoverable on this box"
336	                .to_string(),
337	        ),
338	    }
339	}
340	
341	/// Execute a plan in order, stopping at the first failure. A permission failure names the fix
342	/// plainly instead of half-working: these writes need root.
343	fn apply(plan: &Plan) -> Result<(), String> {
344	    for (path, token) in plan {
345	        if let Err(e) = std::fs::write(path, token) {
346	            let hint = if e.kind() == std::io::ErrorKind::PermissionDenied {
347	                " (writing cpufreq needs root: rerun under sudo)"
348	            } else {
349	                ""
350	            };
351	            return Err(format!("writing {token:?} to {path}: {e}{hint}"));
352	        }
353	    }
354	    Ok(())
355	}
356	
357	// ---------------------------------------------------------------------------
358	// The state display: read-freq's lines and the --as-config form.
359	// ---------------------------------------------------------------------------
360	
361	/// One CPU's displayable policy state, `None` fields simply omitted from the line.
362	#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
363	struct CpuState {
364	    /// `scaling_governor`.
365	    governor: Option<String>,
366	    /// `energy_performance_preference`.
367	    epp: Option<String>,
368	    /// The boost token (`1` / `0`), per-CPU or global.
369	    boost: Option<String>,
370	    /// `scaling_min_freq` (kHz).
371	    min_khz: Option<u64>,
372	    /// `scaling_max_freq` (kHz).
373	    max_khz: Option<u64>,
374	}
375	
376	/// Read one CPU's displayable state.
377	fn cpu_state(cpu: usize) -> CpuState {
378	    let boost = match freq::read_token(cpu, "boost") {
379	        Some(t) => Some(t),
380	        None => std::fs::read_to_string(GLOBAL_BOOST)
381	            .ok()
382	            .map(|s| s.trim().to_string()),
383	    };
384	    CpuState {
385	        governor: freq::read_token(cpu, "scaling_governor"),
386	        epp: freq::read_token(cpu, "energy_performance_preference"),
387	        boost,
388	        min_khz: freq::read_khz(cpu, "scaling_min_freq"),
389	        max_khz: freq::read_khz(cpu, "scaling_max_freq"),
390	    }
391	}
392	
393	/// kHz as a `GHz` display value with two decimals (`3800000` -> `3.80`).
394	fn ghz(khz: u64) -> String {
395	    format!("{:.2}", khz as f64 / 1e6)
396	}
397	
398	/// A compressed CPU list: `[0,1,2,3,8]` -> `0-3,8`.
399	fn cpu_list(cpus: &[usize]) -> String {
400	    let mut parts: Vec<String> = Vec::new();
401	    let mut i = 0;
402	    while i < cpus.len() {
403	        let start = cpus[i];
404	        let mut end = start;
405	        while i + 1 < cpus.len() && cpus[i + 1] == end + 1 {
406	            i += 1;
407	            end = cpus[i];
408	        }
409	        parts.push(if start == end {
410	            start.to_string()
411	        } else {
412	            format!("{start}-{end}")
413	        });
414	        i += 1;
415	    }
416	    parts.join(",")
417	}
418	
419	/// Render one policy group's state line. `prefix` carries the `cpuN-M: ` label when the box has
420	/// more than one group, and the base-clock suffix rides every line so a cut single line still
421	/// carries it.
422	fn state_line(state: &CpuState, cur: Option<(&'static str, u64)>, prefix: &str) -> String {
423	    let mut parts: Vec<String> = Vec::new();
424	    if let Some(g) = &state.governor {
425	        parts.push(format!("governor={g}"));
426	    }
427	    if let Some(e) = &state.epp {
428	        parts.push(format!("epp={e}"));
429	    }
430	    if let Some(b) = &state.boost {
431	        let word = match b.as_str() {
432	            "1" => "on",
433	            "0" => "off",
434	            other => other,
435	        };
436	        parts.push(format!("boost={word}"));
437	    }
438	    if let (Some(min), Some(max)) = (state.min_khz, state.max_khz) {
439	        parts.push(format!("clamp={}-{}GHz", ghz(min), ghz(max)));
440	    }
441	    if let Some((label, khz)) = cur {
442	        parts.push(format!("{label}={}GHz", ghz(khz)));
443	    }
444	    if let Some(b) = freq::base_clock() {
445	        parts.push(format!("base={}GHz({})", ghz(b.khz), b.source));
446	    }
447	    if parts.is_empty() {
448	        parts.push("cpufreq not exposed".to_string());
449	    }
450	    format!("{prefix}{}", parts.join(" "))
451	}
452	
453	/// The current frequency for a group's first CPU: the delivered average where the driver
454	/// reports one (`avg=`), else the driver's `scaling_cur_freq` (`cur=`, which some drivers
455	/// derive and some report as the requested value, so the label says which file it is).
456	fn cur_freq(cpu: usize) -> Option<(&'static str, u64)> {
457	    if let Some(khz) = freq::read_khz(cpu, "cpuinfo_avg_freq") {
458	        return Some(("avg", khz));
459	    }
460	    freq::read_khz(cpu, "scaling_cur_freq").map(|khz| ("cur", khz))
461	}
462	
463	/// The box's state lines, one per policy group: CPUs sharing an identical (governor, EPP,
464	/// boost, clamp) tuple collapse into one line, and a single-group box (the common case) prints
465	/// exactly one line with no CPU prefix, the shape a prompt or status bar wants.
466	fn state_lines() -> Vec<String> {
467	    let mut groups: std::collections::BTreeMap<CpuState, Vec<usize>> = Default::default();
468	    for cpu in freq::cpus() {
469	        groups.entry(cpu_state(cpu)).or_default().push(cpu);
470	    }
471	    if groups.is_empty() {
472	        return vec!["cpufreq not exposed".to_string()];
473	    }
474	    let one = groups.len() == 1;
475	    groups
476	        .iter()
477	        .map(|(state, cpus)| {
478	            let prefix = if one {
479	                String::new()
480	            } else {
481	                format!("cpu{}: ", cpu_list(cpus))
482	            };
483	            state_line(state, cpus.first().and_then(|&c| cur_freq(c)), &prefix)
484	        })
485	        .collect()
486	}
487	
488	/// Print the current state as a `[freq]` config section, ready to paste into a `toml` fence:
489	/// the answer to pin-freq's refusal when no steady state is declared.
490	fn print_as_config() -> i32 {
491	    let cpus = freq::cpus();
492	    let Some(&first) = cpus.first() else {
493	        eprintln!("error: no CPUs under /sys/devices/system/cpu");
494	        return 1;
495	    };
496	    let states: Vec<CpuState> = cpus.iter().map(|&c| cpu_state(c)).collect();
497	    let state = &states[0];
498	    let Some(governor) = &state.governor else {
499	        eprintln!("error: cpufreq exposes no scaling_governor: nothing to declare");
500	        return 1;
501	    };
502	    println!("[freq]");
503	    if states.iter().any(|s| s != state) {
504	        println!("# cpu policy groups disagree: these are cpu{first}'s values");
505	    }
506	    println!("governor = {governor:?}");
507	    if let Some(epp) = &state.epp {
508	        println!("epp = {epp:?}");
509	    }
510	    match state.boost.as_deref() {
511	        Some("1") => println!("boost = true"),
512	        Some("0") => println!("boost = false"),
513	        Some(other) => println!("# boost token {other:?} unrecognized: declare boost by hand"),
514	        None => {}
515	    }
516	    if let (Some(min), Some(max)) = (
517	        freq::read_khz(first, "cpuinfo_min_freq"),
518	        freq::read_khz(first, "cpuinfo_max_freq"),
519	    ) {
520	        println!(
521	            "# min_mhz / max_mhz omitted: the hardware range ({}-{} MHz)",
522	            min / 1000,
523	            max / 1000
524	        );
525	    }
526	    match freq::base_clock() {
527	        Some(b) => println!(
528	            "# pin_mhz omitted: the base clock ({} MHz from {})",
529	            b.khz / 1000,
530	            b.source
531	        ),
532	        None => println!("# pin_mhz: no base clock discoverable, declare one before pinning"),
533	    }
534	    0
535	}
536	
537	// ---------------------------------------------------------------------------
538	// The command words.
539	// ---------------------------------------------------------------------------
540	
541	/// The `read-freq` command: print the clock state (no root needed), or with `as_config` the
542	/// paste-ready `[freq]` section.
543	pub fn cmd_read_freq(as_config: bool) -> i32 {
544	    if as_config {
545	        return print_as_config();
546	    }
547	    for line in state_lines() {
548	        println!("{line}");
549	    }
550	    0
551	}
552	
553	/// The `pin-freq` command: hold the clock at the resolved target until `restore-freq`. Refuses
554	/// without a declared steady state, because a pin with no declared way home is how a box gets
555	/// stranded.
556	pub fn cmd_pin_freq(cfg: Option<&FreqConfig>, cli_mhz: Option<u64>) -> i32 {
557	    let plan = read_caps().and_then(|caps| {
558	        resolve_steady(cfg, &caps)?;
559	        let (khz, source) = resolve_pin(cfg, cli_mhz)?;
560	        Ok((pin_plan(khz, &caps)?, khz, source))
561	    });
562	    let (plan, khz, source) = match plan {
563	        Ok(p) => p,
564	        Err(e) => {
565	            eprintln!("error: pin-freq: {e}");
566	            return 2;
567	        }
568	    };
569	    if let Err(e) = apply(&plan) {
570	        eprintln!("error: pin-freq: {e}");
571	        return 1;
572	    }
573	    println!(
574	        "pinned at {} MHz ({source}): min = max, boost off",
575	        khz / 1000
576	    );
577	    for line in state_lines() {
578	        println!("{line}");
579	    }
580	    println!("restore with: iiac-perf restore-freq");
581	    0
582	}
583	
584	/// The `restore-freq` command: converge the box to the declared steady state, from any starting
585	/// point, an unclean death's residue included.
586	pub fn cmd_restore_freq(cfg: Option<&FreqConfig>) -> i32 {
587	    let plan = read_caps().and_then(|caps| {
588	        let steady = resolve_steady(cfg, &caps)?;
589	        Ok(restore_plan(&steady, &caps))
590	    });
591	    let plan = match plan {
592	        Ok(p) => p,
593	        Err(e) => {
594	            eprintln!("error: restore-freq: {e}");
595	            return 2;
596	        }
597	    };
598	    if let Err(e) = apply(&plan) {
599	        eprintln!("error: restore-freq: {e}");
600	        return 1;
601	    }
602	    println!("restored the declared [freq] steady state");
603	    for line in state_lines() {
604	        println!("{line}");
605	    }
606	    0
607	}
608	
609	// ---------------------------------------------------------------------------
610	// The --pin-freq run guard.
611	// ---------------------------------------------------------------------------
612	
613	/// The restore plan pre-rendered for the signal handler: C paths and byte tokens, so the
614	/// handler allocates nothing. Set once when a [`RunPin`] engages.
615	static SIGNAL_PLAN: OnceLock<Vec<(CString, Vec<u8>)>> = OnceLock::new();
616	
617	/// SIGINT/SIGTERM handler while a run pin is live: replay the restore plan with raw
618	/// open/write/close (the async-signal-safe subset, which is why `std::fs` is not used here),
619	/// then exit with the conventional 128+signal status.
620	extern "C" fn restore_on_signal(sig: libc::c_int) {
621	    if let Some(plan) = SIGNAL_PLAN.get() {
622	        for (path, token) in plan {
623	            unsafe {
624	                let fd = libc::open(path.as_ptr(), libc::O_WRONLY);
625	                if fd >= 0 {
626	                    libc::write(fd, token.as_ptr().cast(), token.len());
627	                    libc::close(fd);
628	                }
629	            }
630	        }
631	    }
632	    unsafe { libc::_exit(128 + sig) };
633	}
634	
635	/// Arm [`restore_on_signal`] with the pre-rendered `plan` for SIGINT and SIGTERM.
636	fn arm_signal_restore(plan: &Plan) {
637	    let rendered: Vec<(CString, Vec<u8>)> = plan
638	        .iter()
639	        .filter_map(|(path, token)| {
640	            // Sysfs paths built here never contain a NUL, so this cannot skip in practice.
641	            let c = CString::new(path.as_str()).ok()?;
642	            Some((c, token.clone().into_bytes()))
643	        })
644	        .collect();
645	    if SIGNAL_PLAN.set(rendered).is_err() {
646	        return;
647	    }
648	    unsafe {
649	        let mut sa: libc::sigaction = std::mem::zeroed();
650	        sa.sa_sigaction = restore_on_signal as *const () as usize;
651	        libc::sigemptyset(&mut sa.sa_mask);
652	        libc::sigaction(libc::SIGINT, &sa, std::ptr::null_mut());
653	        libc::sigaction(libc::SIGTERM, &sa, std::ptr::null_mut());
654	    }
655	}
656	
657	/// A live run pin: created before the warmup so the whole run executes at the pinned clock,
658	/// held to the end of `main`. Restores the declared steady state on drop (normal exit and
659	/// panic) and via [`restore_on_signal`] on SIGINT/SIGTERM.
660	pub struct RunPin {
661	    /// The pinned frequency (kHz), for the Setup block's row.
662	    pub khz: u64,
663	    /// Where the target came from, for the same row.
664	    pub source: String,
665	    /// The restore plan `Drop` executes.
666	    restore: Plan,
667	}
668	
669	impl RunPin {
670	    /// Validate, pin, and arm the restores. On a pin that fails partway the restore plan runs
671	    /// best-effort before the error returns, so a half-applied pin does not outlive the error
672	    /// message.
673	    pub fn engage(cfg: Option<&FreqConfig>, cli_mhz: Option<u64>) -> Result<RunPin, String> {
674	        let caps = read_caps()?;
675	        let steady = resolve_steady(cfg, &caps)?;
676	        let restore = restore_plan(&steady, &caps);
677	        let (khz, source) = resolve_pin(cfg, cli_mhz)?;
678	        let pin = pin_plan(khz, &caps)?;
679	        if let Err(e) = apply(&pin) {
680	            apply(&restore).ok();
681	            return Err(e);
682	        }
683	        arm_signal_restore(&restore);
684	        Ok(RunPin {
685	            khz,
686	            source,
687	            restore,
688	        })
689	    }
690	}
691	
692	impl Drop for RunPin {
693	    /// Restore the declared steady state, pointing at `restore-freq` if any write fails.
694	    fn drop(&mut self) {
695	        if let Err(e) = apply(&self.restore) {
696	            eprintln!("warning: freq restore failed: {e}. Run `iiac-perf restore-freq`.");
697	        }
698	    }
699	}
